for (const [index, label, text] of [[1,"Earthquake factor","Select E. Earthquake is a root, so its local factor is the prior P of E."],[2,"Alarm factor","Select A. Alarm has Burglary and Earthquake as parents, so its table is P of A given B and E."],[3,"John factor","Select J. JohnCalls has only Alarm as a parent, giving P of J given A."],[4,"Mary factor","Select M. MaryCalls likewise contributes P of M given A. We have now visited every local factor in the joint."]]) actionSegment(13, label, text, { type:"click", selector:"nav[aria-label='Choose a Bayesian-network variable'] button", index, label }, ".slide-content h3", 0);
for (const [index, label, text] of [[1,"Collider closed","Choose Collider closed. Burglary and Earthquake are independent before Alarm or its descendants are observed because the unobserved collider blocks their path."],[2,"Explaining away","Choose Explaining away. Observing Alarm opens the collider path, so evidence for Earthquake changes belief in Burglary. Competing causes become dependent through their observed effect."],[0,"Return to common cause","Return to Common cause. Conditioning on Alarm blocks the fork from Alarm to the two callers, making JohnCalls independent of MaryCalls given Alarm in this network."]]) actionSegment(14, label, text, { type:"click", selector:"nav[aria-label='Choose a graphical-independence case'] button", index, label }, ".search-review-studio li", 1);
for (const [index, label, text] of [[1,"Expand factors","Click Next to expand the five local network factors and the two hidden sums."],[2,"Enumerate burglary true","Click Next to sum the four hidden assignments compatible with burglary and both calls."],[3,"Enumerate burglary false","Click Next to compute the larger no-burglary mass. Evidence raises burglary belief without erasing alternative explanations."],[4,"Normalize posterior","Click Next to normalize both masses. The burglary posterior is about point two eight four, a large update from the prior but far from certainty."]]) actionSegment(16, label, text, { type:"click", selector:".frontier-trace section button", index:1, label }, ".frontier-queues article", Math.min(index-1,2));
for (const [index, label, text] of [[1,"Audit decision","Choose Decision. With a class prior included, the classifier is MAP; maximum likelihood omits the prior."],[2,"Audit parameters","Choose Parameters. Only Gaussian Naive Bayes estimates means and variances; other variants learn counts or categorical probabilities."],[3,"Audit robustness","Choose Robustness. Correlated or duplicated features can repeat evidence and distort confidence, so irrelevant does not mean harmless."],[0,"Return to assumption","Return to Assumption. Features are conditionally independent given the class, not marginally independent across the full population."]]) actionSegment(24, label, text, { type:"click", selector:"nav[aria-label='Choose a Naive Bayes evaluation claim'] button", index, label }, ".search-review-studio li", 2);

